def symbols():
    nm=subprocess.check_output(['mips-linux-gnu-nm','-n',str(ROOT/'conker/build/conker.us.elf')],text=True)
    answer={row.split()[2]:int(row.split()[0],16)for row in nm.splitlines()if len(row.split())==3}
    answer['.rodata']=POOL
    return answer

def programs():
    truth=(ROOT/'conker/conker.us.bin').read_bytes()
    oldwords=list(struct.unpack_from('>477I',truth,ROM));pool=truth[POOL_ROM:POOL_ROM+336]
    # Both input tables and IEEE constants belong to the existing data owner.
    actual=sections(ROOT/'conker/build/conker.us.elf')
    matches=[blob[POOL-base:POOL-base+336]for base,blob in actual.values()if base<=POOL and POOL+336<=base+len(blob)]
    assert matches==[pool]
    obj=OUT/'selected.o';raw,refs=payload(obj,NAME);words=bound_blob(raw,refs,symbols())
    rawpool,identities=normalized_pools(obj)['.rodata'];newpool=bytearray(rawpool)
    for at,owner,offset in identities:
        assert owner==NAME
        struct.pack_into('>I',newpool,at,ENTRY+offset)
    assert len(newpool)==336 and len(identities)==79
    return ((oldwords,pool),(words,bytes(newpool)))

def main():
    before=(OUT/'production-baseline'/SOURCE).read_text()
    assert (ROOT/SOURCE).read_text()==before and body(before,NAME)=='s32 func_150169A0() {\n    return 0;\n}'
    record=json.loads((OUT/'production-baseline/fingerprints.json').read_text())
    for name,digest in record['inputs'].items():assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==digest,name
    obj,diag=compile_owner(ROOT,OUT,before.replace(body(before,NAME),SELECTED),'selected')
    base,base_diag=compile_owner(ROOT,OUT,before,'baseline')
    assert diag==base_diag=='' and same_functions(base,obj,(NAME,))==2
    raw,refs=payload(obj,NAME);p=programs();words=p[1][0]
    assert len(words)==476 and words[0]==0x27bdffa8
    report=dict(words=476,retail_words=477,frame=88,retail_saved_registers=1,candidate_saved_registers=2,neighbors=2,binding_sites=len(refs),pool_bytes=len(p[1][1]),jump_entries=79,real_word_differences=sum(a!=b for a,b in zip(p[0][0],words))+abs(len(p[0][0])-len(words)),raw_sha256=hashlib.sha256(raw).hexdigest(),inputs_unchanged=len(record['inputs']),uncredited=True)
    (OUT/'raw-report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report),flush=True)
if __name__=='__main__':main()
